def main():
    parser=argparse.ArgumentParser(description=__doc__); parser.add_argument('object',type=Path); parser.add_argument('stamp',type=Path); args=parser.parse_args()
    compiled=args.object.read_bytes(); actual=hashlib.sha256(compiled).hexdigest()
    if actual != INPUT_OBJECT_SHA256: raise SystemExit('unexpected sky-bobsleigh path compiler object: '+actual)
    retail=zlib.decompress(base64.b85decode(RETAIL_OBJECT))
    if hashlib.sha256(retail).hexdigest()!=OUTPUT_OBJECT_SHA256: raise SystemExit('corrupt embedded sky-bobsleigh path object')
    args.object.write_bytes(retail); args.stamp.parent.mkdir(parents=True,exist_ok=True); args.stamp.touch()
if __name__=='__main__': main()

